<section class="admin-section container"><a href="<?= e(url('admin')) ?>">← Administración</a><h1>Revisión de reportes</h1><p>Aceptar un reporte permite usarlo como información ciudadana; no lo convierte en oficial.</p>
<nav class="pagination" aria-label="Estado"><?php foreach(['pendiente','aceptado','rechazado'] as $value): ?><a href="<?= e(url('admin/reportes?estado='.$value)) ?>"><?= e(ucfirst($value)) ?></a><?php endforeach; ?></nav>
<div class="content-cards"><?php foreach($rows as $row): ?><article class="content-card"><h2><?= e($row['sucursal']) ?></h2><p><?= e(local_datetime($row['fecha'].' '.$row['hora'])) ?> · Demanda <?= e($row['nivel_demanda']) ?></p><p>Personas: <?= e($row['personas_esperando']===null?'Sin dato':(string)$row['personas_esperando']) ?> · Minutos: <?= e($row['tiempo_espera']===null?'Sin dato':(string)$row['tiempo_espera']) ?></p><p><?= e($row['observaciones']??'') ?></p>
<?php if($row['estado_revision']==='pendiente'): ?><form class="form-actions" method="post" action="<?= e(url('admin/reportes/revisar')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="version" value="<?= e($row['version']) ?>"><button class="button" name="decision" value="aceptado">Aceptar</button><button class="button button-secondary" name="decision" value="rechazado">Rechazar</button></form><?php endif; ?>
</article><?php endforeach; ?></div>
<?php if($rows===[]): ?><p>No hay reportes en esta página.</p><?php endif; ?>
<nav class="pagination" aria-label="Páginas"><?php if($page>1): ?><a href="<?= e(url('admin/reportes?estado='.$state.'&pagina='.($page-1))) ?>">Anterior</a><?php endif; ?><?php if(count($rows)===30): ?><a href="<?= e(url('admin/reportes?estado='.$state.'&pagina='.($page+1))) ?>">Siguiente</a><?php endif; ?></nav></section>
